INSERT INTO "public"."fommenu" ("pk", "parentpk", "cprompt", "chref", "cfunction", "isort", "ilevel", "crole", "objective", "cexec", "jscript", "lparent", "chtml", "jqclass", "class", "private") VALUES ('4', '1', 'Set Permissions And Roles', '', '', '10', '0', '', 'Create Wizard', '', '$(document).off(''.fomPerms'');
$(''#add-perm,#add-role,#save-settings'').off(''.fomPerms'');

var colors = [''black'',''dodgerblue'',''crimson'',''forestgreen'',''purple'',''fuchsia'',''goldenrod'',''navy''];

function addPermRow(level, label) {
  $(''#perm-body'').append(''<tr><td><input type="number" class="perm-level" value="'' + level + ''" style="width:70px"></td><td><input type="text" class="perm-label" value="'' + label + ''" style="width:200px"></td><td><button class="del-perm-row">X</button></td></tr>'');
}

function addRoleRow(code, label) {
  $(''#roles-body'').append(''<tr><td><input type="text" class="role-code" value="'' + code + ''" maxlength="2" style="width:50px"></td><td><input type="text" class="role-label" value="'' + label + ''" style="width:200px"></td><td><button class="del-role-row">X</button></td></tr>'');
}

$.getJSON(''/getSettings'', function(data) {
  $(''#perm-body'').empty();
  $(''#roles-body'').empty();
  (data.permissionLevels || []).slice().sort(function(a,b){ return a.level - b.level; }).forEach(function(p) { addPermRow(p.level, p.label); });
  (data.roles || []).forEach(function(r) { addRoleRow(r.code, r.label); });
});

$(''#add-perm'').on(''click.fomPerms'', function() { addPermRow('''', ''''); });
$(''#add-role'').on(''click.fomPerms'', function() { addRoleRow('''', ''''); });
$(document).on(''click.fomPerms'', ''.del-perm-row'', function() { $(this).closest(''tr'').remove(); });
$(document).on(''click.fomPerms'', ''.del-role-row'', function() { $(this).closest(''tr'').remove(); });

$(''#save-settings'').on(''click.fomPerms'', function() {
  var permissionLevels = [];
  $(''#perm-body tr'').each(function() {
    var level = parseInt($(this).find(''.perm-level'').val(), 10);
    var label = $(this).find(''.perm-label'').val().trim();
    if (!isNaN(level) && label) permissionLevels.push({level: level, label: label});
  });
  if (permissionLevels.length > 7) {
    $(''#save-status'').text(''Maximum 7 permission levels allowed.'').css(''color'',''red'');
    return;
  }
  var roles = [];
  $(''#roles-body tr'').each(function() {
    var code = $(this).find(''.role-code'').val().trim();
    var label = $(this).find(''.role-label'').val().trim();
    if (code && label) roles.push({code: code, label: label});
  });
  $(''#save-status'').text(''Saving...'').css(''color'',''black'');
  $.ajax({
    url: ''/saveSettings'',
    method: ''POST'',
    contentType: ''application/json'',
    data: JSON.stringify({permissionLevels: permissionLevels, roles: roles}),
    success: function() { $(''#save-status'').text(''Saved successfully.'').css(''color'',''green''); },
    error: function() { $(''#save-status'').text(''Error saving settings.'').css(''color'',''red''); }
  });
});', 'f', '<div style="padding:20px;font-family:sans-serif">
  <h2>Permission Levels</h2>
  <p style="color:#666">Colors are assigned automatically by order. Maximum 7 levels.</p>
  <table border="1" cellpadding="6" cellspacing="0">
    <thead><tr><th>Level</th><th>Label</th><th></th></tr></thead>
    <tbody id="perm-body"></tbody>
  </table>
  <br><button id="add-perm">+ Add Level</button>
  <h2>Roles</h2>
  <table border="1" cellpadding="6" cellspacing="0">
    <thead><tr><th>Code</th><th>Label</th><th></th></tr></thead>
    <tbody id="roles-body"></tbody>
  </table>
  <br><button id="add-role">+ Add Role</button>
  <br><br>
  <button id="save-settings" style="padding:8px 20px;font-size:14px">Save Settings</button>
  <span id="save-status" style="margin-left:15px"></span>
</div>', 'fom-lc', '', NULL);
INSERT INTO "public"."fommenu" ("pk", "parentpk", "cprompt", "chref", "cfunction", "isort", "ilevel", "crole", "objective", "cexec", "jscript", "lparent", "chtml", "jqclass", "class", "private") VALUES ('5', '1', 'Add a Menu', '', '', '40', '0', '', 'Add Menu Prompts -Batch', '', '$(''#btnAddMenu'').off(''.fomAdd'').on(''click.fomAdd'', function() {
  var text = $(''#txtMenuInput'').val().trim();
  if (!text) { $(''#menuAddResult'').text(''Please enter menu text.'').css(''color'',''red''); return; }
  $(''#menuAddResult'').text(''Adding...'').css(''color'',''black'');
  $.ajax({
    url: ''/addMenu'',
    method: ''POST'',
    contentType: ''application/json'',
    data: JSON.stringify({ text: text }),
    success: function(res) {
      $(''#menuAddResult'').text(''Added '' + res.count + '' item(s). Reloading menu...'').css(''color'',''green'');
      $(''#txtMenuInput'').val('''');
      setTimeout(function() {
        fetch(''/getMenuData?_='' + Date.now())
          .then(function(r) { return r.text(); })
          .then(function(html) { document.getElementById(''fomMenu'').innerHTML = html; });
      }, 500);
    },
    error: function(xhr) {
      var msg = xhr.responseJSON && xhr.responseJSON.error ? xhr.responseJSON.error : ''Unknown error'';
      $(''#menuAddResult'').text(''Error: '' + msg).css(''color'',''red'');
    }
  });
});', 'f', '<div style="padding:20px;font-family:sans-serif">
  <h2>Add Menu Items</h2>
