INSERT INTO "public"."fommenu" ("pk", "parentpk", "cprompt", "chref", "cfunction", "isort", "ilevel", "crole", "objective", "cexec", "jscript", "lparent", "chtml", "jqclass", "class", "private") VALUES ('22', '1', 'Browse Widgets FOM', '', '', '60', '0', '', NULL, NULL, 'fetch(''/checkLogin'')
    .then(r => r.json())
    .then(data => {
      if (!data.loggedIn) {
        window.location.href = ''/login.html'';
      } else {
        initPage();
      }
    })
    .catch(() => { window.location.href = ''/login.html''; });

  function initPage() {
 
   let allWidgets = [];
    let currentEditId = null;

    const tabs = document.querySelectorAll(''.w-tab'');
    const paneList = document.getElementById(''w-pane-list'');
    const paneForm = document.getElementById(''w-pane-form'');
    const searchInput = document.getElementById(''w-search'');
    const countSpan = document.getElementById(''w-count'');
    const gridDiv = document.getElementById(''w-grid'');
    const addBtn = document.getElementById(''w-add-btn'');
    const saveBtn = document.getElementById(''w-save-btn'');
    const deleteBtn = document.getElementById(''w-delete-btn'');
    const cancelBtn = document.getElementById(''w-cancel-btn'');
    const formTitle = document.getElementById(''w-form-title'');
    const formStatus = document.getElementById(''w-form-status'');
    const fId = document.getElementById(''f-id'');
    const fChead = document.getElementById(''f-chead'');
    const fCbody = document.getElementById(''f-cbody'');
    const fIgroup = document.getElementById(''f-igroup'');
    const fJscript = document.getElementById(''f-jscript'');

    // Tab switching
    tabs.forEach(tab => {
      tab.addEventListener(''click'', () => {
        tabs.forEach(t => t.classList.remove(''active''));
        tab.classList.add(''active'');
        paneList.style.display = tab.dataset.tab === ''list'' ? ''block'' : ''none'';
        paneForm.style.display = tab.dataset.tab === ''form'' ? ''block'' : ''none'';
        if (tab.dataset.tab === ''list'') {
          searchInput.value = '''';
          renderTable(allWidgets);
        }
      });
    });

    // Load widgets list
    async function loadWidgets() {
      try {
        const resp = await fetch(''/getTable?name=widgets'');
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const data = await resp.json();
        // Handle both array and {columns, rows} responses
        allWidgets = Array.isArray(data) ? data : (data.rows || []);
        renderTable(allWidgets);
      } catch (err) {
        gridDiv.innerHTML = `<p style="color:red">Error: ${err.message}</p>`;
      }
    }

    // Render table
    function renderTable(widgets) {
      if (!widgets || !widgets.length) {
        gridDiv.innerHTML = ''<p style="color:#aaa">No widgets found.</p>'';
        countSpan.textContent = '''';
        return;
      }
      countSpan.textContent = `(${widgets.length} total)`;
      const cols = [''id'', ''chead'', ''cbody'', ''igroup'', ''jscript''];
      let html = ''<table><thead><tr>'';
      cols.forEach(col => {
        html += `<th>${col}</th>`;
      });
      html += ''<th style="width:100px">Actions</th></tr></thead><tbody>'';
      widgets.forEach(w => {
        html += ''<tr>'';
        cols.forEach(col => {
          let val = w[col] || '''';
          if (col === ''cbody'' || col === ''jscript'') {
            val = (String(val).substring(0, 50) + (String(val).length > 50 ? ''…'' : ''''));
          }
          html += `<td>${escapeHtml(val)}</td>`;
        });
        html += `<td>
          <button class="w-btn w-btn-edit" onclick="window.editWidget(${w.id})">Edit</button>
          <button class="w-btn w-btn-delete" onclick="window.deleteWidgetConfirm(${w.id})">Del</button>
        </td></tr>`;
      });
      html += ''</tbody></table>'';
      gridDiv.innerHTML = html;
    }

    // Search filter
    searchInput.addEventListener(''input'', (e) => {
      const query = e.target.value.toLowerCase();
      if (!query) {
        renderTable(allWidgets);
        return;
      }
      const filtered = allWidgets.filter(w =>
        (w.chead && w.chead.toLowerCase().includes(query)) ||
        (w.cbody && w.cbody.toLowerCase().includes(query)) ||
        (w.id && String(w.id).includes(query))
      );
      renderTable(filtered);
    });

    // Add new widget
    addBtn.addEventListener(''click'', () => {
      currentEditId = null;
      fId.value = '''';
      fChead.value = '''';
      fCbody.value = '''';
      fIgroup.value = 0;
      fJscript.value = '''';
      formTitle.textContent = ''New Widget'';
      deleteBtn.style.display = ''none'';
      formStatus.textContent = '''';
      tabs[1].click();
    });

    // Edit widget
    window.editWidget = async (id) => {
      try {
        const resp = await fetch(`/widget/${id}`);
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const w = await resp.json();
        currentEditId = id;
        fId.value = w.id;
        fChead.value = w.chead || '''';
        fCbody.value = w.cbody || '''';
        fIgroup.value = w.igroup || 0;
        fJscript.value = w.jscript || '''';
        formTitle.textContent = `Edit Widget #${id}`;
        deleteBtn.style.display = ''inline-block'';
        formStatus.textContent = '''';
        tabs[1].click();
      } catch (err) {
        formStatus.textContent = `Error: ${err.message}`;
        formStatus.style.color = ''red'';
      }
    };

    // Save widget
    saveBtn.addEventListener(''click'', async () => {
      const payload = {
        chead: fChead.value.trim(),
        cbody: fCbody.value.trim(),
        igroup: parseInt(fIgroup.value, 10) || 0,
        jscript: fJscript.value.trim()
      };

      formStatus.textContent = ''Saving…'';
      formStatus.style.color = ''#888'';

      try {
        if (currentEditId) {
          const resp = await fetch(`/widget/${currentEditId}`, {
            method: ''PUT'',
            headers: { ''Content-Type'': ''application/json'' },
            body: JSON.stringify(payload)
          });
          if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        } else {
          // Create new widget via INSERT
          const resp = await fetch(''/widget'', {
            method: ''POST'',
            headers: { ''Content-Type'': ''application/json'' },
            body: JSON.stringify(payload)
          });
          if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        }
        formStatus.textContent = ''Saved!'';
        formStatus.style.color = ''#2e7d32'';
        setTimeout(() => { tabs[0].click(); loadWidgets(); }, 800);
      } catch (err) {
        formStatus.textContent = `Error: ${err.message}`;
        formStatus.style.color = ''red'';
      }
    });

    // Delete widget
    window.deleteWidgetConfirm = async (id) => {
      if (!confirm(`Delete widget ${id}? This cannot be undone.`)) return;
      currentEditId = id;
      formStatus.textContent = ''Deleting…'';
      formStatus.style.color = ''#888'';
      try {
        const resp = await fetch(`/widget/${id}`, { method: ''DELETE'' });
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        formStatus.textContent = ''Deleted!'';
        formStatus.style.color = ''#2e7d32'';
        setTimeout(() => { tabs[0].click(); loadWidgets(); }, 800);
      } catch (err) {
        formStatus.textContent = `Error: ${err.message}`;
        formStatus.style.color = ''red'';
      }
    };

    // Cancel
    cancelBtn.addEventListener(''click'', () => {
      tabs[0].click();
    });

    // Helper
    function escapeHtml(text) {
      const map = { ''&'': ''&amp;'', ''<'': ''&lt;'', ''>'': ''&gt;'', ''"'': ''&quot;'', "''": ''&#039;'' };
      return String(text).replace(/[&<>"'']/g, m => map[m]);
    }

    // Load on init
    loadWidgets();
  }

', NULL, '<style>
  #w-wrap { font-family: Arial, sans-serif; font-size: 13px; padding: 10px; }
  #w-wrap h3 { margin: 0 0 12px; color: #2c3e50; font-size: 16px; }

  /* Tabs */
  #w-tabs { display: flex; gap: 0; margin-bottom: 14px; border-bottom: 2px solid #2c3e50; }
  .w-tab { padding: 6px 18px; cursor: pointer; background: #eee; border: 1px solid #ccc; border-bottom: none; font-size: 13px; }
  .w-tab.active { background: #2c3e50; color: white; border-color: #2c3e50; }

  /* List */
  #w-toolbar { display: flex; gap: 8px; align-items: center; margin-bottom: 8px; flex-wrap: wrap; }
  #w-search { padding: 5px 8px; border: 1px solid #ccc; border-radius: 3px; font-size: 13px; width: 220px; }
  #w-count  { color: #888; font-size: 12px; }
  .w-btn { padding: 5px 14px; border: none; border-radius: 3px; cursor: pointer; font-size: 13px; }
  .w-btn-add    { background: #2e7d32; color: white; }
  .w-btn-add:hover { background: #1b5e20; }
  .w-btn-edit   { background: #1976D2; color: white; padding: 3px 9px; font-size: 12px; }
  .w-btn-delete { background: #c62828; color: white; padding: 3px 9px; font-size: 12px; }

  #w-grid { overflow-y: auto; max-height: calc(100vh - 200px); }
  #w-grid table { border-collapse: collapse; width: 100%; }
  #w-grid thead th { position: sticky; top: 0; z-index: 2; background: #2c3e50; color: white;
    padding: 6px 10px; border: 1px solid #1a252f; cursor: pointer; white-space: nowrap;
    user-select: none; text-align: left; }
  #w-grid tbody td { padding: 4px 10px; border: 1px solid #ddd; }
  #w-grid tbody tr:nth-child(even) { background: #f5f7fa; }
  #w-grid tbody tr:hover { background: #e3eaf8; }

  /* Form */
  #w-form-wrap { max-width: 600px; }
  #w-form-title { font-size: 15px; font-weight: bold; color: #2c3e50; margin-bottom: 14px; }
  .w-field { margin-bottom: 10px; display: flex; flex-direction: column; }
  .w-field label { font-weight: bold; color: #555; margin-bottom: 3px; }
  .w-field input[type=text], .w-field input[type=number], .w-field textarea {
    padding: 5px 8px; border: 1px solid #ccc; border-radius: 3px; font-size: 13px; }
  .w-field textarea { resize: vertical; min-height: 80px; font-family: monospace; }
  #w-form-btns { margin-top: 14px; display: flex; gap: 8px; }
  #w-form-status { font-size: 12px; margin-top: 8px; }
</style>

<div id="w-wrap">
  <h3>Widgets</h3>
  <div id="w-tabs">
    <div class="w-tab active" data-tab="list">List</div>
    <div class="w-tab" data-tab="form">Add / Edit</div>
  </div>

  <!-- LIST -->
  <div id="w-pane-list">
    <div id="w-toolbar">
      <input id="w-search" type="text" placeholder="Search header or body…">
      <span id="w-count"></span>
      <button class="w-btn w-btn-add" id="w-add-btn">+ Add Widget</button>
    </div>
    <div id="w-grid"><p style="color:#aaa">Loading…</p></div>
  </div>

  <!-- FORM -->
  <div id="w-pane-form" style="display:none">
    <div id="w-form-title">New Widget</div>
    <div id="w-form-wrap">
      <input type="hidden" id="f-id">
      <div class="w-field">
        <label>Header (chead)</label>
        <input type="text" id="f-chead" maxlength="500">
      </div>
      <div class="w-field">
        <label>Body (cbody)</label>
        <textarea id="f-cbody"></textarea>
      </div>
      <div class="w-field">
        <label>Group (igroup)</label>
        <input type="number" id="f-igroup" value="0">
      </div>
      <div class="w-field">
        <label>JavaScript (jscript)</label>
        <textarea id="f-jscript"></textarea>
      </div>
      <div id="w-form-btns">
        <button class="w-btn w-btn-add" id="w-save-btn">Save</button>
        <button class="w-btn" id="w-delete-btn" style="background:#c62828;color:white;display:none">Delete</button>
        <button class="w-btn" id="w-cancel-btn" style="background:#607D8B;color:white">Cancel</button>
      </div>
      <div id="w-form-status"></div>
    </div>
  </div>
</div>', 'fom-lc', NULL, NULL);
