INSERT INTO "public"."fommenu" ("pk", "parentpk", "cprompt", "chref", "cfunction", "isort", "ilevel", "crole", "objective", "cexec", "jscript", "lparent", "chtml", "jqclass", "class", "private") VALUES ('24', '15', 'Photo-TItle-Caption', 'PhotoID.html', '', '40', '0', '', NULL, NULL, 'function loadPhoto(id) {
