    .then((r) => r.json())
    .then(({ title, caption }) => {
      document.getElementById(''photo-title'').textContent = title;
      document.getElementById(''photo-caption'').textContent = caption;
      document.getElementById(''photo-img'').src = `/photo?id=${id}`;
