-- public.widgets: 10 rows
INSERT INTO "public"."widgets" ("id", "chead", "cbody", "igroup", "jscript") VALUES ('4', 'The John Wayne Principle', 'A searing portrait of the insidious attractions of corporate life, "The John Wayne Principle" tells the story a cynical, anti-establishment trust-fund kid who is picked to succeed his father as CEO of a multinational corporation.  Instead of turning down the post, as his ambitious, business-minded sister had expected, he decides to sign on for a year, sending the company''s stock into a tailspin.  His sister''s attempts to undermine his tenure only serve to fuel his enthusiasm for the job, and, as their sibling rivalry takes on sexual-political overtones, one is left to wonder if this rebel riding rough-shod on the company wants to break or break in the system.', '1', NULL);
INSERT INTO "public"."widgets" ("id", "chead", "cbody", "igroup", "jscript") VALUES ('5', 'Men', '', '1', 'spreadsheet(''movies'',''performer_name, movie_name, character_name, rating, box_office'')');
INSERT INTO "public"."widgets" ("id", "chead", "cbody", "igroup", "jscript") VALUES ('6', 'The Secret Narrative Of The Phone Book', 'A romantic comedy hijacked by a conspiracy thriller.  It follows a sexy freedom fighter''s daring plan to corrupt a global media conglomerate by seducing two of its employees at the same time. Its tongue-in-cheek techno-paranoia seriously questions the possibility of a genuine connection between human beings', '2', '');
INSERT INTO "public"."widgets" ("id", "chead", "cbody", "igroup", "jscript") VALUES ('7', 'Ludlow Fair', 'A winsome one-act by Lanford Wilson that offers a glimpse into the lives of two twentysomething roommates, broke and lonely and crammed into their tiny first apartment in Manhattan.  A production of recent Northwestern alums.', '1', '');
INSERT INTO "public"."widgets" ("id", "chead", "cbody", "igroup", "jscript") VALUES ('8', 'BYE MOM! Or, How NOT to Bury Your Mother', 'Take one Jewish mother too stubborn to die, an obsessed daughter and her married lover, three sons: a nebbish, a nerd, and an airhead.  Toss in an insufferable daughter-in-law and convene them all in Florida.  And what do you get?  A nasty little comedy about the lack of family values and the joy of family feuding', '1', '<script>document.getElementsbyTagName(''cbody'').color(''red'')');
INSERT INTO "public"."widgets" ("id", "chead", "cbody", "igroup", "jscript") VALUES ('9', 'Tricks of the Trade', 'A world premiere drama about four young gay men during one very, very long night at a West Village bar as they look for Mr. Right, Mr. Right Now, and whomever else they can find to pass the time and ease their needs. A play William M. Hoffman, author of "As Is," calls "''The Boys in the Band'' for this generation."', '2', '');
INSERT INTO "public"."widgets" ("id", "chead", "cbody", "igroup", "jscript") VALUES ('10', 'Waiting For Godot', 'Waiting for Godot...an all time classic...a comic tragic play that speaks of human perplexity, of kindness, of hope.  The characters are reduced to mere waiting, in game playing to endure the waiting and the audience wonders whether Godot will ever come. Beckett''s symbolic character brings an unease that makes room for imagining and interpretation in reference to anything outside of itself...the absurdity of life itself!', '2', '');
INSERT INTO "public"."widgets" ("id", "chead", "cbody", "igroup", "jscript") VALUES ('11', 'The Pinter Project', 'Two Pinter Plays- The Birthday Party and The Homecoming - in Rotating Repertory

The Homecoming offers a darkly comedic view of feminine power, while The Birthday Party explores the destruction of the artist by powerful authoritarian figures.

Schedule varies – call ahead or go to www.pinterproject.com for info.
', NULL, NULL);
INSERT INTO "public"."widgets" ("id", "chead", "cbody", "igroup", "jscript") VALUES ('12', '12 Angry Women', 'If hell hath no fury  like a woman scorned – well, imagine a dozen of them at one time!  A comedy for women and the men who infuriate them,  Featuring  sketches, spoofs and solos, this sexy, sassy showcase examines the reasons why  many females get burned, get mad, then get even.
', NULL, NULL);
INSERT INTO "public"."widgets" ("id", "chead", "cbody", "igroup", "jscript") VALUES ('13', 'Yet To Evolve', 'This play shows how we must all evolve in order to live a happier life. For some, evolve can mean to get over the past and forgive, for others evolve can mean learning to accept those that are different from us.', NULL, NULL);
SELECT setval(pg_get_serial_sequence('"public"."widgets"', 'id'), COALESCE(MAX("id"), 1), MAX("id") IS NOT NULL) FROM "public"."widgets";
